import{_ as o,o as t,c as a,a2 as n}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),r={name:"guide/changelog.md"};function i(d,e,s,c,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to ReelForge are documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/TerminalDZ/vidcreat/compare/v1.0.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;[Unreleased]&quot;">​</a></h2><h2 id="_1-0-0-2026-11-01" tabindex="-1"><a href="https://github.com/TerminalDZ/vidcreat/releases/tag/v1.0.0" target="_blank" rel="noreferrer">1.0.0</a> - 2026-11-01 <a class="header-anchor" href="#_1-0-0-2026-11-01" aria-label="Permalink to &quot;[1.0.0] - 2026-11-01&quot;">​</a></h2><p>First public release, under the Apache License 2.0 (documentation and examples under CC BY 4.0).</p><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><strong>Visual editor</strong> (<code>reelforge edit</code>): canvas with zoom/pan, hover and selection, drag and resize with smart guides, nudging and in-place text editing; layers panel with drag-to-reorder and rename; component library with drag-and-drop; schema-driven inspector for every property (scrubbable numbers, theme color swatches, word-anchored times, lists, effects, states, YAML view); multi-track timeline (scenes, script cues, layer tracks, waveform, SFX) with magnetic snapping to spoken words; undo/redo across <code>episode.yaml</code> and <code>cues.json</code>; ⌘K command palette, context menus, a shortcut sheet, resizable panels and a first-run tour. Edits keep the comments and formatting of <code>episode.yaml</code>.</li><li><strong>Project dashboard</strong> (<code>reelforge studio</code>): create English or Arabic episodes, upload recordings (WAV, MP3, M4A, OGG, FLAC…), open the editor, validate and render with live progress, play and download.</li><li><strong>Cues mode</strong>: mark sentence starts with Space at 0.5×–1× speed, nudge by 50/10 ms, re-mark any line, word mode, snap to onset, undo, autosave; or drag cues on the timeline.</li><li><strong>Automatic cues</strong> (<code>reelforge align</code>, <strong>Auto-mark from voice</strong> in Cues mode, <strong>Auto cues</strong> on the dashboard, MCP <code>align_cues</code>): every line and word aligned to the recording. Works without any model (pause detection and dynamic programming over the known script, about 0.05 s per minute of voice). Optional speech models (<code>reelforge align --setup</code> downloads them once into the user cache, about 180 MB; alignment runs offline afterwards): Whisper word timings matched to the script by fuzzy DTW, and Silero VAD for speech versus music and noise. Measured on recorded speech with known timings: every line within 100 ms (mean 15 ms), also under background music. Hand-marked cues are never replaced without confirmation; in the editor the change is one undo step.</li><li><strong>Smart insert</strong>: suggestions per line in the editor&#39;s Insert panel and MCP <code>suggest_scene</code>. A keyword dictionary (English and Arabic) picks the component, fills its props from the line and makes it enter on the word that names it. Optional local LLM (through Ollama, <code>qwen2.5:1.5b</code> by default) with output constrained to the component schemas.</li><li><strong>Review mode</strong>: true 1080×1920 preview synced to the audio, hot reload on save, platform safe-zone, stage and element-box overlays, every check with click-to-select, and an error banner that keeps the last good frame.</li><li><strong>Agent integration (optional)</strong>: <code>reelforge mcp</code>, a Model Context Protocol server (create, read, edit, validate, preview frames as images, align, render) plus instruction files (<code>AGENTS.md</code>, <code>CLAUDE.md</code>, <code>GEMINI.md</code>, …) and ready-made MCP configurations.</li><li><strong>Examples</strong>: the 9-episode &quot;System Design&quot; series in English, the same series in Arabic, and a 45-second product intro.</li><li><strong>21 animated components</strong>: title, label, code, node, arrow, chip, stamp, table, lanes, checklist, counter, meter, timeline, grid, bucket, phone, quote, particles, trap, cta, icon.</li><li><strong>Motion</strong>: 17 enter and 9 exit animations (including <code>reveal</code>, <code>spring</code>, <code>drop</code>, <code>blur</code> and <code>wipe</code>), per-element easing (<code>smooth</code>, <code>snappy</code>, <code>gentle</code>, <code>linear</code>), six scene transitions (crossfade, cut, slide-up, zoom, push, blur) and slow camera moves (drift, push-in, pull-out). Everything renders with sub-pixel precision, so slow moves stay smooth; frame-by-frame motion tests guard against jumps and stutter. The inspector previews any animation with one click.</li><li><strong>Captions in English and Arabic</strong>: word-by-word karaoke highlight, correct RTL/LTR mixing, <code>الـ term</code> kept together, punctuation on the correct side.</li><li><strong>Audio</strong>: procedural sound effects, and voice mastering to −14 LUFS with ducking and a limiter.</li><li><strong>Voice noise cleanup</strong>: <code>audio.denoise: true</code>, <code>render --denoise</code> or a checkbox in the render dialogs. RNNoise (bundled 290 KB model, FFmpeg <code>arnndn</code>) runs before loudness mastering; about 15 dB less noise between sentences in tests, with the voice level unchanged.</li><li><strong>Rendering</strong>: deterministic parallel frame capture; an H.264 master (CRF 18) and a size-capped share file, plus SRT captions, a contact sheet and <code>publish.md</code>. Every output is verified (codec, profile, pixel format, frame rate, AAC 48 kHz, faststart, size).</li><li><strong>Validation</strong>: 14 rules with <code>file:line:col</code> locations and fix hints, including V-14 pacing (lines spoken faster than 3.5 words/s, a hook that starts after 3 s, silences of 1.5 s or more).</li><li><strong>Themes and presets</strong> in editable YAML; <code>reelforge theme new --accent #hex</code>.</li><li><strong>CLI</strong>: <code>studio</code>, <code>new</code> (<code>--lang</code>), <code>edit</code>, <code>cue</code>, <code>dev</code>, <code>align</code>, <code>mcp</code>, <code>validate</code>, <code>render</code> (<code>--all</code>), <code>snap</code> (<code>--cover</code>), <code>doctor</code>, <code>schema</code>, <code>theme new</code>.</li><li>One-command installers for Windows, macOS and Linux.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li>Renders failed the output check with <code>pixel format yuvj420p</code> on FFmpeg 7+: frames are now converted to limited-range BT.709 yuv420p.</li><li>The dashboard and editor are responsive (side panels become drawers on tablets and phones).</li></ul>',10)])])}const p=o(r,[["render",i]]);export{m as __pageData,p as default};
